const crypto = require('crypto');

const HMAC_SECRET   = $env['N8N_WEBHOOK_HMAC_SECRET'];
const MAX_SKEW_SECS = 300;

const item    = $input.first();
const headers = item.json.headers || {};

const sigHeader = headers['x-eduai-signature-256']     || '';
const tsHeader  = headers['x-eduai-timestamp']         || '';
const idempKey  = headers['x-eduai-idempotency-key']   || '';

// Timestamp freshness
const nowSecs = Math.floor(Date.now() / 1000);
const tsSecs  = parseInt(tsHeader, 10);
if (isNaN(tsSecs) || Math.abs(nowSecs - tsSecs) > MAX_SKEW_SECS) {
  throw new Error(`Timestamp rejected: skew=${nowSecs - tsSecs}s`);
}

// HMAC verify
const rawBody  = item.json.rawBody || JSON.stringify(item.json.body);
const expected = 'sha256=' + crypto.createHmac('sha256', HMAC_SECRET).update(rawBody, 'utf8').digest('hex');
const sigBuf = Buffer.from(sigHeader);
const expBuf = Buffer.from(expected);
if (sigBuf.length !== expBuf.length || !crypto.timingSafeEqual(sigBuf, expBuf)) {
  throw new Error('Signature verification failed');
}

const body = typeof rawBody === 'string' ? JSON.parse(rawBody) : rawBody;
return [{ json: { ...body, _idempotency_key: idempKey, _verified: true } }];

// Extract and validate payload fields
const item    = $input.first();
const payload = item.json.payload || {};

const confidence     = parseFloat(payload.confidence_score ?? -1);
const conf0to4       = parseInt(payload.confidence_0_to_4  ?? -1, 10);
const threshold      = parseFloat(payload.threshold        ?? 0.35);
const fileId         = payload.file_id     || '';
const userId         = payload.user_id     || '';
const role           = payload.role        || '';
const submissionId   = payload.submission_id || '';
const modelUsed      = payload.model_used  || 'unknown';
const pipeline       = payload.pipeline    || 'phase12_langgraph';
const analysisType   = payload.analysis_type || '';

if (!fileId || !userId) {
  throw new Error('Malformed payload: file_id and user_id are required');
}

if (confidence < 0 || confidence > 1) {
  throw new Error(`Invalid confidence_score: ${confidence}`);
}

// Severity tier: critical (<0.20), high (<0.35), moderate (<0.50)
let severity = 'moderate';
if (confidence < 0.20) severity = 'critical';
else if (confidence < threshold) severity = 'high';

return [{
  json: {
    event_id:      item.json.event_id,
    correlation_id: item.json.correlation_id,
    timestamp:     item.json.timestamp,
    file_id:       fileId,
    user_id:       userId,
    role,
    submission_id: submissionId,
    confidence,
    conf0to4,
    threshold,
    model_used:    modelUsed,
    pipeline,
    analysis_type: analysisType,
    severity,
    escalation_required: confidence < threshold,
  }
}];

// ============================================================
// Build escalation record
// In production: POST to your alerting endpoint, Slack webhook,
// PagerDuty API, or insert to Supabase escalations table via
// HTTP Request node. This node prepares the structured payload.
// ============================================================

const item = $input.first();

const escalation = {
  id:              `esc-${item.json.event_id}`,
  created_at:      new Date().toISOString(),
  file_id:         item.json.file_id,
  user_id:         item.json.user_id,
  role:            item.json.role,
  submission_id:   item.json.submission_id,
  confidence:      item.json.confidence,
  conf0to4:        item.json.conf0to4,
  threshold:       item.json.threshold,
  severity:        item.json.severity,
  model_used:      item.json.model_used,
  pipeline:        item.json.pipeline,
  analysis_type:   item.json.analysis_type,
  correlation_id:  item.json.correlation_id,
  event_id:        item.json.event_id,
  status:          'open',
  resolution:      null,
};

console.log(JSON.stringify({ level: 'warn', message: 'low_confidence_escalation', ...escalation }));

return [{ json: { escalation } }];

// Confidence is acceptable — log for audit trail only
const item = $input.first();
console.log(JSON.stringify({
  level: 'info',
  message: 'confidence_acceptable',
  event_id:   item.json.event_id,
  confidence: item.json.confidence,
  threshold:  item.json.threshold,
  file_id:    item.json.file_id,
}));
return [{ json: { ...item.json, escalation_required: false } }];
